/**
 * Cascade behind `ProjectService.archiveProject`. Stamps only issues that are
 * still live and returns that count, so previously archived issues keep their
 * original `archivedAt` and the usage delta matches a live recount.
 */
export async function archiveIssuesForProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const rows = getDb()
    .update(issues)
    .set(archivePatch())
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          eq(issues.projectId, projectId),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .returning({ id: issues.id })
    .all();

  return rows.length;
}

